import {deviceId,startDeviceBridge,executeDeviceOperation} from './device-storage.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),num=v=>Number(v)||0;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date()),isoLocal=v=>new Date(v).toISOString(),localInput=v=>{const d=new Date(v||Date.now());return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const pages=[['home','⌘','首页','每一次，都算数。'],['train','↗','训练','把下一组，练得更好。'],['nutrition','◉','饮食','记录，才能看见改变。'],['progress','▥','进展','看见你的渐进超负荷。'],['settings','⚙','设置','你的数据，你的选择。']];
const S={token:sessionStorage.getItem('kilo-web-token'),data:null,page:'home',storage:null,catalog:new Map(),draft:null,editor:'workout',editId:null,key:null,day:today(),restEnd:0,startedAt:null,bridgeStop:null,progressId:null,progress:null,selectedMuscle:null,anatomyMode:'recovery',bodyGender:'male'};
const errors={browser_device_offline:'绑定的本地浏览器未在线。请保持绑定页面打开，或在设置中切换存储。',device_not_bound:'此浏览器未绑定，请在设置中绑定此设备。',backend_session_invalid:'App 云端登录已过期，请在设置中重新连接。',backend_membership_required:'App 云端保存需要有效会员。',membership_required:'此功能需要有效会员。',server_storage_required:'请先在设置中选择服务器模式，再创建完整权限 MCP 令牌。',mcp_token_invalid:'MCP 授权已失效，请重新创建。',revision_conflict:'记录发生冲突，请刷新后重试。',record_changed_refresh:'记录已变化，请刷新后再编辑。',idempotency_key_reused:'重复请求的内容不一致，请重新提交。',invalid_credentials:'账号或密码不正确。'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
async function api(route,body,method,signal){const r=await fetch('/v1/agent'+route,{method:method||(body?'POST':'GET'),headers:{...(S.token?{authorization:'Bearer '+S.token}:{}),...(body?{'content-type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal});let value;try{value=await r.json();}catch{throw new Error('服务响应不完整');}if(!r.ok)throw new Error(value.error||value.code||'request_failed');return value;}
async function auth(route,body){const r=await fetch('/v1/auth/'+route,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const value=await r.json();if(!r.ok)throw new Error(value.error||'登录失败');return value;}
function safeTask(fn){return async e=>{try{await fn(e);}catch(err){toast(errors[err.message]||err.message);}};}
function empty(title,detail,action){return `<div class="empty"><b>${esc(title)}</b><span>${esc(detail)}</span>${action?`<div class="actions" style="justify-content:center">${action}</div>`:''}</div>`;}
function metric(label,value,unit,sub=''){return `<div class="card metric"><div class="label">${label}</div><span class="number">${esc(value)}</span><span class="unit">${unit}</span>${sub?`<div class="sub">${sub}</div>`:''}</div>`;}
function fmtDate(v){return new Date(v).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function nameOf(e){return e.name||S.catalog.get(e.exerciseId)?.name||e.exerciseId;}
function renderNav(){for(const id of ['#nav','#mobile-nav'])$(id).innerHTML=pages.map(([id,icon,label])=>`<button class="nav-link ${S.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');$('#page-title').textContent=pages.find(p=>p[0]===S.page)[3];$('#account').textContent=S.token?'退出账号':'登录';$('#storage-label').textContent=S.storage?.mode==='browser'?'本地浏览器 · '+(S.storage.deviceId===deviceId?'此设备':'其他设备'):S.data?.backend?.connected?'App 会员云端':'此网站服务器';}
function render(){renderNav();if(!S.data){$('#content').innerHTML=`<div class="card signin-placeholder"><span class="eyebrow">YOUR PERSONAL TRAINING SPACE</span><h2>每一组的努力，<br>都值得被记住。</h2><p>记录动作、重量、次数和感受，追踪饮食与身体变化。让你的 AI 通过 MCP 帮你记录。</p><button class="primary" data-action="login">登录并开始</button><button data-page="settings">存储与连接设置</button></div>`;if(S.page==='settings'&&S.token)renderSettings();return;}
 if(S.page==='home')renderHome();if(S.page==='train')renderTrain();if(S.page==='nutrition')void renderNutrition();if(S.page==='progress')void renderProgress();if(S.page==='settings')renderSettings();animateCards();}
function animateCards(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('#content').querySelectorAll('.card').forEach((card,i)=>card.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:420,delay:Math.min(i,7)*35,easing:'cubic-bezier(.2,.75,.25,1)',fill:'both'}));}
async function initializeStorage(){S.storage=await api('/storage');S.bridgeStop?.();S.bridgeStop=null;if(S.storage.mode==='browser'&&S.storage.deviceId===deviceId){S.bridgeStop=startDeviceBridge(S.storage.userId,api);for(let i=0;i<15;i++){const st=await api('/storage');if(st.online){S.storage=st;break;}await new Promise(r=>setTimeout(r,100));}}}
async function load(){await initializeStorage();try{S.data=await api('/bootstrap');S.storage=S.data.storage;restoreDraft();render();$('#save-state').textContent=S.storage.mode==='browser'?'记录仅保存在此浏览器':'记录保存在当前服务器账户';}catch(e){if(['browser_device_offline','backend_session_invalid','backend_membership_required'].includes(e.message)){S.data=null;S.page='settings';render();toast(errors[e.message]);}else throw e;}}
async function refresh(){S.data=await api('/bootstrap');S.storage=S.data.storage;render();}
const draftStorageKey=()=>`traintool-draft:${S.storage?.userId}:${S.storage?.mode}:${S.data?.backend?.remoteUserId||''}`;
function persistDraft(){if(!S.storage)return;localStorage.setItem(draftStorageKey(),JSON.stringify({draft:S.draft,editor:S.editor,editId:S.editId,key:S.key,restEnd:S.restEnd,startedAt:S.startedAt}));}
function restoreDraft(){const raw=localStorage.getItem(draftStorageKey());if(raw){try{const saved=JSON.parse(raw);Object.assign(S,saved);}catch{}}else if(S.data?.activeWorkout){const {id,updatedAt,volume,effectiveSets,exerciseIds,prs,prDetails,...d}=S.data.activeWorkout;S.draft=d;S.editor='workout';S.key=uid();}}
function dataExercises(){return S.data?.workouts||[];}
function renderHome(){const d=S.data,weekly=d.dashboard.weekly,all=dataExercises(),sets=all.reduce((n,w)=>n+(w.effectiveSets||0),0);$('#content').innerHTML=`<div class="grid four-col">${metric('本周训练',weekly.sessions,'次','过去 7 天的完成记录')}${metric('本周有效组',weekly.sets,'组','已完成的非热身组')}${metric('累计训练',all.length,'次',`共 ${sets} 个有效组`)}${metric('本周训练容量',Math.round(weekly.volume).toLocaleString(),'kg','已完成组的重量 × 次数')}</div><div class="grid two-col section-gap"><section class="card"><div class="card-title"><div><span class="eyebrow">BODY MAP</span><h2>身体的训练信号</h2></div><button data-action="toggle-body-mode" class="quiet">${S.anatomyMode==='recovery'?'恢复状态':'训练组数'} ⇄</button></div><div class="row between"><span class="muted">${S.bodyGender==='male'?'男性':'女性'}肌肉图 · 点选部位查看</span><button class="quiet small" data-action="toggle-gender">切换图像</button></div><div class="anatomy">${bodyMap('front')}${bodyMap('back')}</div><div class="muscle-list">${(d.dashboard.appRecovery||d.dashboard.muscles).map(m=>`<button class="muscle-chip" data-muscle="${esc(m.id)}"><span>${esc(m.name)}</span><span>${S.anatomyMode==='recovery'?(m.recoveryPercent===null?'未知':m.recoveryPercent+'%'):m.weeklySets+' 组'}</span></button>`).join('')}</div><div id="muscle-detail"></div><p class="muted section-gap">${esc(d.dashboard.appRecoveryMethod||d.dashboard.recoveryMethod)}</p></section><div class="grid"><section class="card hero"><span class="eyebrow">YOUR NEXT SESSION</span><h2>${S.draft?'接着练完，今天这一组。':'把计划，变成今天的行动。'}</h2><p>按组记录。重量、次数和真实感受，一起留下。</p><button data-action="new-workout">${S.draft?'继续训练 ↗':'开始一次训练 ↗'}</button><small>支持休息计时与训练计划</small></section><section class="card"><div class="card-title"><h3>最近训练</h3><button class="quiet small" data-page="train">全部 →</button></div>${all.slice(0,3).map(workoutRow).join('')||empty('还没有训练记录','新建训练，或让外部 AI 通过 MCP 帮你记录。')}</section><section class="card"><div class="card-title"><h3>你的训练计划</h3><button class="quiet small" data-action="new-plan">＋ 创建</button></div>${d.plans.slice(0,3).map(planRow).join('')||empty('从一套计划开始','动作、组数、重量、次数与休息，都能保存。')}</section></div></div>`;attachBodyMasks();}
const regionMap={'chest':'chest','upper-back':'upper-back','lower-back':'lower-back','deltoids':'deltoids','biceps':'biceps','triceps':'triceps','forearm':'forearm','abs':'abs','obliques':'abs','gluteal':'gluteal','quadriceps':'quadriceps','hamstring':'hamstring','calves':'calves','trapezius':'upper-back','adductors':'quadriceps','tibialis':'calves'};
const front=['trapezius','deltoids','chest','biceps','obliques','abs','forearm','quadriceps','calves'],back=['trapezius','deltoids','upper-back','lower-back','triceps','forearm','gluteal','hamstring','calves'];
function bodyMap(side){return `<div class="body-stack" data-side="${side}" role="img" aria-label="${side==='front'?'正面':'背面'}肌肉图"><img class="base" src="/agent/muscles/${S.bodyGender}-${side}-base.svg" alt="">${(side==='front'?front:back).map(slug=>{const m=(S.data.dashboard.appRecovery||S.data.dashboard.muscles).find(m=>m.id===regionMap[slug]);return `<span class="muscle-layer" style="--heat:${S.anatomyMode==='recovery'?recoveryColor(m?.recoveryPercent):volumeColor(m?.weeklySets)};mask-image:url('/agent/muscles/${S.bodyGender}-${side}-${slug}.svg')" aria-hidden="true"></span>`;}).join('')}</div>`;}
function recoveryColor(percent){return percent==null?'#9c9892':percent<40?'#d75e65':percent<60?'#e58b45':percent<80?'#e6ba49':percent<95?'#94b765':'#399ca7';}
function volumeColor(n){return !n?'#bab4ad':n<6?'#f0c389':n<16?'#f08b3d':'#c45112';}
let masks;async function attachBodyMasks(){masks??=await (await fetch('/agent/muscles/masks.json')).json();for(const el of $('#content').querySelectorAll('.body-stack'))el.onclick=e=>{const r=el.getBoundingClientRect(),image=el.querySelector('.base'),ratio=image.naturalWidth/image.naturalHeight||660.46/1206.46,w=Math.min(r.width,r.height*ratio),h=w/ratio,left=r.left+(r.width-w)/2,top=r.top+(r.height-h)/2,x=Math.floor((e.clientX-left)/w*48),y=Math.floor((e.clientY-top)/h*88);if(x<0||x>=48||y<0||y>=88)return;const regions=masks.genders[S.bodyGender][el.dataset.side];const hit=Object.entries(regions).filter(([,v])=>v.rows[y]&&((BigInt('0x'+v.rows[y])>>BigInt(47-x))&1n)).sort((a,b)=>a[1].pixelCount-b[1].pixelCount)[0];if(hit)showMuscle(regionMap[hit[0]]);};}
function showMuscle(id){S.selectedMuscle=id;const m=(S.data.dashboard.appRecovery||S.data.dashboard.muscles).find(m=>m.id===id);if(!m)return;$('#muscle-detail').innerHTML=`<div class="muscle-info"><div class="row between"><b>${esc(m.name)}</b><span class="pill">本周 ${m.trainingCount??0} 次 · ${m.weeklySets} 组</span></div><p class="small">${m.recoveryPercent===null?'暂无可推算记录':`恢复估算 ${m.recoveryPercent}%`}${m.hoursSinceLast!=null?` · 距上次 ${Math.floor(m.hoursSinceLast)} 小时`:''}${m.hoursTo95!=null?` · 预计 ${Math.ceil(m.hoursTo95)} 小时后达到 95%`:''}</p><div class="recovery-bar"><span style="width:${m.recoveryPercent||0}%"></span></div><div class="row wrap">${(m.exercises||[]).map(n=>`<a class="small" href="https://www.douyin.com/search/${encodeURIComponent(n+' 训练 教学')}" target="_blank" rel="noopener noreferrer">${esc(n)} 教学 ↗</a>`).join('')}</div></div>`;}
function workoutRow(w){return `<div class="list-row"><div><strong>${esc(w.name)}</strong><p>${fmtDate(w.date)} · ${w.effectiveSets||0} 组 · ${Math.round(w.volume||0)} kg</p>${w.note?`<p>${esc(w.note.slice(0,70))}</p>`:''}</div><div class="list-actions"><button data-detail="${esc(w.id)}">详情</button><button data-edit-workout="${esc(w.id)}">编辑</button></div></div>`;}
function planRow(p){return `<div class="list-row"><div><strong>${esc(p.name)}</strong><p>${esc(p.folder||'我的计划')} · ${p.exercises.length} 动作 · ${p.exercises.reduce((n,e)=>n+e.sets.length,0)} 组</p></div><div class="list-actions"><button data-start-plan="${esc(p.id)}">开始</button><button data-edit-plan="${esc(p.id)}">编辑</button></div></div>`;}
function newDraft(plan=false,record){const fresh=!S.draft;if(!plan&&!record&&!fresh){S.page='train';render();return;}S.editor=plan?'plan':'workout';S.editId=record?.id||null;S.key=uid();S.draft=record?structuredClone(record):{name:plan?'我的训练计划':'自由训练',date:new Date().toISOString(),durationSeconds:0,note:'',exercises:[],folder:'我的计划'};S.startedAt=plan?null:Date.now();S.restEnd=0;S.page='train';persistDraft();render();}
function setDefaults(){return {id:uid(),type:'work',weight:0,reps:8,restSeconds:90,completed:false,failed:false,note:'',rpe:null,rir:null,durationSeconds:null,weightText:'',speedKph:null,inclinePercent:null};}
function renderTrain(){const d=S.draft;$('#content').innerHTML=`<div class="tabs"><button class="${d?'active':''}" data-action="new-workout">当前训练</button><button data-action="new-plan">＋ 创建计划</button><button data-action="pick-exercise-library">动作库</button></div>${d?editorMarkup(d):`<section class="card hero"><span class="eyebrow">MAKE IT COUNT</span><h2>准备好下一组了吗？</h2><p>自由训练，或从已保存的计划开始。</p><button data-action="new-workout">＋ 开始训练</button></section>`}<div class="grid two-col section-gap"><section class="card"><div class="card-title"><h2>训练计划</h2><span class="pill">${S.data.plans.length} 套</span></div>${S.data.plans.map(planRow).join('')||empty('还没有计划','创建后可反复使用，也可以让 AI 通过 MCP 创建。')}</section><section class="card"><div class="card-title"><h2>训练历史</h2><span class="pill">${S.data.workouts.length} 次</span></div>${S.data.workouts.map(workoutRow).join('')||empty('记录从今天开始','每组的重量、次数、休息和备注都会保留。')}</section></div>`;}
function editorMarkup(d){return `<section class="card"><div class="card-title"><h2>${S.editor==='plan'?'计划编辑':S.editId?'编辑训练记录':'进行中的训练'}</h2><span class="pill orange">${S.editor==='plan'?'保存后可复用':'逐组记录'}</span></div><div class="workout-head"><input data-draft="name" value="${esc(d.name)}" aria-label="训练名称">${S.editor==='plan'?`<input data-draft="folder" value="${esc(d.folder||'我的计划')}" aria-label="计划文件夹">`:`<input type="datetime-local" data-draft="date" value="${localInput(d.date)}" aria-label="训练日期"><span id="workout-timer" class="timer">00:00</span>`}</div><div id="rest-banner" class="rest-banner" ${S.restEnd>Date.now()?'':'hidden'}><span>组间休息 <strong id="rest-time">00:00</strong></span><div><button data-action="rest-add">＋15 秒</button><button data-action="rest-skip">跳过</button></div></div>${d.exercises.map(exerciseEditor).join('')||empty('添加第一个动作','选择 App 动作库中的动作，稳定 ID 可用于历史比较。')}<button data-action="pick-exercise">＋ 添加动作</button><label class="section-gap">${S.editor==='plan'?'计划备注':'整次训练备注'}<textarea data-draft="note" placeholder="今天的状态、感受和需要记住的事">${esc(d.note||'')}</textarea></label>${S.editor==='workout'?`<label>总时长（秒，可手动调整）<input data-draft="durationSeconds" type="number" min="0" max="86400" value="${d.durationSeconds||0}"></label>`:''}<div class="actions"><button class="primary" data-action="save-draft">${S.editor==='plan'?'保存计划':S.editId?'保存修改':'完成并保存训练'}</button>${S.editor==='workout'&&!S.editId?'<button data-action="save-active">保存进行中训练（AI 可读写）</button><button data-action="reload-active">载入 AI 更新</button>':''}<button class="quiet" data-action="discard-draft">清空草稿</button></div><p class="muted small section-gap">${S.editor==='workout'?'仅勾选“完成”的组计入统计；每组备注、动作备注和整次备注均会保存。':''}编辑草稿自动保留在此浏览器，点击保存后写入当前选择的存储。</p></section>`;}
function exerciseEditor(e,i){return `<div class="exercise-card"><div class="card-title"><div><span class="eyebrow">EXERCISE ${String(i+1).padStart(2,'0')}</span><h3>${esc(nameOf(e))}</h3><span class="small muted">${esc(e.exerciseId)}</span></div><div class="row"><button class="quiet small" data-move-exercise="${i}:-1" aria-label="上移动作" ${i===0?'disabled':''}>↑</button><button class="quiet small" data-move-exercise="${i}:1" aria-label="下移动作" ${i===S.draft.exercises.length-1?'disabled':''}>↓</button><button class="quiet small" data-equipment="${esc(e.exerciseId)}">器械照片</button><button class="quiet small" data-exercise-history="${esc(e.exerciseId)}">历史 ↗</button><button class="quiet danger" data-remove-exercise="${i}" aria-label="移除动作">×</button></div></div><div class="horizontal-scroll"><table class="set-table"><thead><tr><th>组</th><th>类型</th><th>kg</th><th>次数</th><th>休息 / 秒</th><th>完成</th><th>备注 / 感受</th><th></th></tr></thead><tbody>${e.sets.map((s,j)=>`<tr><td>${j+1}</td><td><select data-set="type" data-i="${i}" data-j="${j}">${[['work','正式'],['warmup','热身'],['drop','递减'],['failure','力竭']].map(([k,v])=>`<option value="${k}" ${s.type===k?'selected':''}>${v}</option>`).join('')}</select></td><td><input data-set="weight" data-i="${i}" data-j="${j}" type="number" step="0.5" min="0" max="2000" value="${s.weight}" aria-label="第 ${j+1} 组重量"></td><td><input data-set="reps" data-i="${i}" data-j="${j}" type="number" min="0" max="10000" value="${s.reps}" aria-label="第 ${j+1} 组次数"></td><td><input data-set="restSeconds" data-i="${i}" data-j="${j}" type="number" min="0" max="7200" value="${s.restSeconds}" aria-label="第 ${j+1} 组休息时间"></td><td><input class="set-done" data-set="completed" data-i="${i}" data-j="${j}" type="checkbox" ${s.completed?'checked':''} aria-label="第 ${j+1} 组完成"></td><td><input class="set-note" data-set="note" data-i="${i}" data-j="${j}" value="${esc(s.note)}" placeholder="状态、感受、补充" aria-label="第 ${j+1} 组备注"></td><td><button class="quiet" data-remove-set="${i}:${j}" aria-label="删除第 ${j+1} 组">×</button></td></tr>`).join('')}</tbody></table></div><details class="set-details"><summary>每组的 RPE / RIR、有氧数据与目标次数</summary>${e.sets.map((s,j)=>`<div class="form-grid section-gap"><b class="span-two small">第 ${j+1} 组</b>${[['rpe','RPE（1–10）'],['rir','RIR（0–5）'],['durationSeconds','时长 / 秒'],['speedKph','速度 / km/h'],['inclinePercent','坡度 / %'],['targetMin','目标最少次数'],['targetMax','目标最多次数']].map(([k,l])=>`<label>${l}<input type="number" step="0.1" data-set="${k}" data-i="${i}" data-j="${j}" value="${s[k]??''}"></label>`).join('')}<label>辅助 / 自重描述<input data-set="weightText" data-i="${i}" data-j="${j}" value="${esc(s.weightText||'')}"></label><label class="row"><input type="checkbox" data-set="failed" data-i="${i}" data-j="${j}" ${s.failed?'checked':''}>本组未达到目标</label></div>`).join('')}</details><div class="row between section-gap"><button class="small" data-add-set="${i}">＋ 添加一组</button><label class="row small">动作休息 / 秒 <input data-exercise="restSeconds" data-i="${i}" type="number" min="0" value="${e.restSeconds||0}" style="width:80px"></label></div><label class="section-gap">动作备注<input data-exercise="note" data-i="${i}" value="${esc(e.note||'')}" placeholder="动作调整、疼痛反馈、下次提示"></label></div>`;}
function cleanExercise(e){return {id:e.id,exerciseId:e.exerciseId,restSeconds:e.restSeconds||0,note:e.note||'',collapsed:false,supersetId:e.supersetId||null,sets:e.sets.map(s=>Object.fromEntries(Object.entries(s).filter(([k])=>['id','type','weight','plannedWeight','reps','targetMin','targetMax','restSeconds','completed','failed','rpe','rir','note','durationSeconds','weightText','speedKph','inclinePercent'].includes(k))))};}
function cleanDraft(){const d=S.draft,record={name:d.name,note:d.note||'',exercises:d.exercises.map(cleanExercise)};if(S.editor==='plan')record.folder=d.folder||'我的计划';else Object.assign(record,{date:d.date,durationSeconds:d.durationSeconds||Math.floor((Date.now()-(S.startedAt||Date.now()))/1000),startTime:d.startTime||d.date.slice(11,16),gymId:d.gymId||null});return record;}
async function save(kind,record,recordId,version,key=uid()){return api('/records/'+kind,{idempotencyKey:key,action:recordId?'update':'create',...(recordId?{recordId}:{}),...(version?{expectedVersion:version}:{}),record});}
async function saveDraft(active=false){if(!S.draft.exercises.length)throw new Error('请先添加动作。');const kind=active?'activeWorkout':S.editor;if(kind==='workout'&&!S.draft.exercises.some(e=>e.sets.some(s=>s.completed)))throw new Error('请勾选已完成的训练组，再保存训练。');const result=await save(kind,cleanDraft(),active?undefined:S.editId,active?undefined:S.draft.updatedAt,S.key);toast(active?'当前训练已保存，AI 可以通过 MCP 继续编辑。':'已保存，每一组和备注都已记录。');if(!active){if(S.editor==='workout'&&!S.editId){try{await api('/records/activeWorkout',{idempotencyKey:uid(),action:'delete',recordId:'active-workout'});}catch{}}S.draft=null;S.editId=null;S.restEnd=0;S.key=null;persistDraft();}else S.key=uid();await refresh();return result;}
let pickingForLibrary=false;async function openExercises(library=false){pickingForLibrary=library;$('#exercise-dialog').showModal();await searchExercises();}
async function searchExercises(){const result=await api('/app-exercises?query='+encodeURIComponent($('#exercise-query').value)+'&muscle='+encodeURIComponent($('#muscle-filter').value)+'&equipment='+encodeURIComponent($('#equipment-filter').value));for(const e of result.records)S.catalog.set(e.id,e);for(const [id,values,label] of [['#muscle-filter',result.muscles,'所有肌群'],['#equipment-filter',result.equipment,'所有器械']]){const select=$(id),selected=select.value;select.innerHTML=`<option value="">${label}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');}$('#exercise-count').textContent=`${result.total} 个匹配动作${result.total>150?' · 当前展示前 150 个，请缩小搜索范围':''}`;$('#exercise-results').innerHTML=result.records.map(e=>`<div class="exercise-result"><div class="row">${e.imageAsset?`<img loading="lazy" src="/agent/exercise-media/${esc(e.imageAsset)}" alt="${esc(e.name)}" class="exercise-thumb">`:'<span class="badge">↗</span>'}<div><b>${esc(e.name)}</b><p class="small muted">${esc(e.muscle)} · ${esc(e.equipment)}</p></div><button class="small" data-equipment="${esc(e.id)}">器械照片</button><button class="primary small" data-add-exercise="${esc(e.id)}">${pickingForLibrary?'训练':'添加'}</button></div><details><summary class="small muted">动作说明与演示</summary><p class="small">${esc(e.summary||'')}</p>${e.gifAsset?`<img class="exercise-demo" loading="lazy" src="/agent/exercise-media/${esc(e.gifAsset)}" alt="动作演示">`:''}<ol class="small">${(e.steps||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ol><p class="small muted">辅助肌群：${esc(e.secondary||'未提供')}<br>${esc(e.attribution||'')}</p><a class="small" target="_blank" rel="noopener noreferrer" href="https://www.douyin.com/search/${encodeURIComponent(e.name+' 训练 教学')}">抖音教学 ↗</a></details></div>`).join('')||empty('没有找到动作','试试中文名、英文名或更短的关键词。');}
async function renderNutrition(){const day=S.day;$('#content').innerHTML=`<section class="card"><div class="card-title"><h2>今天吃了什么</h2><input class="date-picker" id="nutrition-date" type="date" value="${day}" aria-label="饮食日期"></div><div id="nutrition-overview"><p class="muted">读取当前存储的记录…</p></div></section><div class="grid two-col section-gap"><section class="card"><div class="card-title"><h2>记录一餐</h2><span class="pill">支持 AI 估算后调整</span></div>${nutritionForm()}</section><section class="card"><h2>每日目标</h2><p class="muted">由你或外部 AI 根据资料确定。保存依据，随时调整；网页不自动生成饮食建议。</p>${goalForm()}<div class="note section-gap">拍照发给你的 AI → AI 估算食物与份量 → 调用 save_nutrition_entry → 在这里显示。无需把照片上传此网站。</div></section></div><section class="card section-gap"><div class="card-title"><h2>饮食时间线</h2><button data-action="add-water">＋ 250 ml 饮水</button></div><div id="nutrition-timeline"></div></section>`;try{const result=await api('/nutrition-day?date='+day);if(S.page!=='nutrition'||S.day!==day)return;const {intake,goal,remainingCalories:remaining}=result;$('#nutrition-overview').innerHTML=`<div class="nutrition-overview"><div class="calorie-ring" style="--percent:${goal?Math.min(100,intake.calories/goal.calories*100):0}"><div class="ring-value"><strong>${Math.round(intake.calories)}</strong><span>已记录 kcal</span></div></div><div class="grid" style="flex:1"><div class="row between"><div><span class="muted">目标</span><h2>${goal?goal.calories:'未设置'} <small class="muted">${goal?'kcal':''}</small></h2></div><div><span class="muted">${remaining!=null&&remaining<0?'超出目标':'剩余额度'}</span><h2>${remaining==null?'—':Math.abs(Math.round(remaining))} <small class="muted">${remaining!=null?'kcal':''}</small></h2></div></div><div class="row wrap small"><span>蛋白 ${Math.round(intake.proteinGrams)} g</span><span>碳水 ${Math.round(intake.carbsGrams)} g</span><span>脂肪 ${Math.round(intake.fatGrams)} g</span><span>饮水 ${Math.round(intake.waterMl)} ml</span></div><span class="muted small">${result.containsEstimates?'包含估算值，可按实际份量调整。':'仅统计已保存记录。未记录不代表没有摄入。'}</span></div></div>`;$('#nutrition-timeline').innerHTML=result.records.map(r=>`<div class="list-row"><div><strong>${esc(r.foodName)}</strong><span class="pill orange">${esc(r.mealType)}</span><p>${fmtDate(r.recordedAt)} · ${esc(r.amount)} · ${Math.round(r.calories)} kcal${r.estimated?' · 估算':''}</p>${r.note?`<div class="note">${esc(r.note)}</div>`:''}${r.recognitionWarnings?.length?`<p class="small">${r.recognitionWarnings.map(esc).join('；')}</p>`:''}</div><div class="list-actions"><button data-edit-meal="${esc(r.id)}">调整</button><button class="danger" data-delete-record="nutrition:${esc(r.id)}">删除</button></div></div>`).join('')||empty('这一天还没有记录','手动记录，或让 AI 通过 MCP 保存。');if(goal){const f=$('#goal-form');for(const k of ['calories','goalType','basis','source'])if(f.elements[k])f.elements[k].value=goal[k]||'';f.dataset.recordId=goal.id;f.dataset.version=goal.updatedAt||'';}}catch(e){toast(errors[e.message]||e.message);}}
function nutritionForm(){return `<form id="nutrition-form" class="form-grid"><label>食物名称<input name="foodName" placeholder="例如：鸡肉饭" required></label><label>餐次<select name="mealType">${['早餐','午餐','晚餐','加餐','其他'].map(n=>`<option>${n}</option>`).join('')}</select></label><label>时间<input type="datetime-local" name="recordedAt" value="${S.day+'T'+localInput().slice(11)}" required></label><label>份量<input name="amount" placeholder="例如：一碗，约 300 g"></label>${[['calories','热量 / kcal'],['proteinGrams','蛋白质 / g'],['carbsGrams','碳水 / g'],['fatGrams','脂肪 / g']].map(([k,l])=>`<label>${l}<input type="number" name="${k}" min="0" step="0.1" value="${k==='calories'?'':'0'}" required></label>`).join('')}<label class="span-two">备注<textarea name="note" placeholder="份量、状态或补充内容"></textarea></label><label class="row span-two"><input type="checkbox" name="estimated">热量 / 营养素为估算</label><div class="actions span-two"><button class="primary" type="submit">保存饮食记录</button><button type="reset">重置</button></div></form>`;}
function goalForm(){return `<form id="goal-form" class="form-grid"><label>目标热量 / kcal<input type="number" name="calories" min="100" max="20000" required></label><label>目标类型<select name="goalType">${['减脂','维持','增肌','其他'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="span-two">计算依据 / 调整说明<textarea name="basis" placeholder="例如：外部 AI 根据身高、体重、年龄、活动量估算；由我确认"></textarea></label><label>来源<select name="source"><option value="user">我设置的</option><option value="external-ai">外部 AI 计算</option></select></label><button type="submit" class="primary">保存当日目标</button></form>`;}
function chart(values,label,unit){const valid=values.filter(v=>Number.isFinite(v.value));if(!valid.length)return empty('暂无趋势','记录训练或身体数据后显示。');const min=Math.min(...valid.map(v=>v.value)),max=Math.max(...valid.map(v=>v.value)),range=max-min||1;const points=valid.map((v,i)=>({x:45+i*(450/Math.max(1,valid.length-1)),y:140-(v.value-min)/range*100,...v}));return `<svg class="chart" viewBox="0 0 540 175" role="img" aria-label="${esc(label)}"><line x1="40" y1="140" x2="510" y2="140"/><line x1="40" y1="40" x2="510" y2="40"/><text x="4" y="44">${Math.round(max)}</text><text x="4" y="144">${Math.round(min)}</text><polyline points="${points.map(p=>p.x+','+p.y).join(' ')}"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3.5"><title>${esc(fmtDate(p.date))}：${p.value} ${unit}</title></circle>`).join('')}<text x="45" y="167">${esc(fmtDate(valid[0].date))}</text><text x="405" y="167">${esc(fmtDate(valid.at(-1).date))}</text></svg>`;}
async function renderProgress(){const ids=[...new Set(S.data.workouts.flatMap(w=>(w.exercises||[]).map(e=>e.exerciseId)))];S.progressId=ids.includes(S.progressId)?S.progressId:ids[0];$('#content').innerHTML=`<div class="grid two-col"><section class="card"><div class="card-title"><h2>动作进展</h2><span class="pill">同一动作 · 历次逐组</span></div><select id="progress-exercise" aria-label="查看动作进展">${ids.map(id=>{const e=S.data.workouts.flatMap(w=>w.exercises).find(e=>e.exerciseId===id);return `<option value="${esc(id)}" ${id===S.progressId?'selected':''}>${esc(nameOf(e))}</option>`;}).join('')}</select><div id="progress-charts"></div></section><section class="card"><h2>身体变化</h2><p class="muted">体重与体脂记录，保留每一次测量。</p>${chart(S.data.weight.slice().reverse().map(w=>({value:w.weightKg,date:w.recordedAt})),'体重趋势','kg')}<form id="weight-form" class="form-grid"><label>体重 / kg<input name="weightKg" type="number" step="0.1" min="1" max="700" required></label><label>体脂 / %（可选）<input name="bodyFatPercent" type="number" step="0.1" min="1" max="80"></label><label>测量时间<input name="recordedAt" type="datetime-local" value="${localInput()}" required></label><label>备注<input name="note" placeholder="例如：起床后测量"></label><button class="primary" type="submit">记录体重</button></form><div class="section-gap">${S.data.weight.slice(0,10).map(w=>`<div class="list-row"><div><b>${w.weightKg} kg</b><p>${fmtDate(w.recordedAt)}${w.bodyFatPercent?' · 体脂 '+w.bodyFatPercent+'%':''} ${esc(w.note||'')}</p></div><button class="quiet danger small" data-delete-record="weight:${esc(w.id)}">删除</button></div>`).join('')}</div></section></div><section class="card section-gap"><h2>每次训练，逐组对比</h2><div id="progress-history"></div></section>`;if(!S.progressId){$('#progress-charts').innerHTML=empty('还没有可比较的动作','记录同一动作的多次训练后查看重量和次数变化。');return;}await loadProgress();}
async function loadProgress(){const id=S.progressId,result=await api('/exercise-progress?exerciseId='+encodeURIComponent(id));if(S.page!=='progress'||S.progressId!==id)return;S.progress=result;$('#progress-charts').innerHTML=`<h3 class="section-gap">完成工作组最大重量 / kg</h3>${chart(result.sessions.map(s=>({value:s.maxWeight,date:s.date})), '历次最大重量','kg')}<h3>完成工作组最多次数</h3>${chart(result.sessions.map(s=>({value:s.maxReps,date:s.date})), '历次最多次数','次')}<p class="chart-legend">两条趋势的最大值可能来自不同组。下方保留每次训练的逐组数据，不能把两条最大值当作同一组表现。</p>`;$('#progress-history').innerHTML=result.sessions.slice().reverse().map((s,i,arr)=>{const previous=arr[i+1];return `<div class="exercise-card"><div class="card-title"><div><h3>${esc(s.name)}</h3><span class="muted">${fmtDate(s.date)}</span></div>${previous?`<span class="pill orange">最大重量 ${((s.maxWeight||0)-(previous.maxWeight||0))>=0?'+':''}${((s.maxWeight||0)-(previous.maxWeight||0)).toFixed(1)} kg · 最多次数 ${((s.maxReps||0)-(previous.maxReps||0))>=0?'+':''}${(s.maxReps||0)-(previous.maxReps||0)}</span>`:'<span class="pill">首次记录</span>'}</div>${setsReadOnly(s.sets)}${s.note?`<div class="note">整次训练：${esc(s.note)}</div>`:''}${[...new Set(s.sets.map(v=>v.exerciseNote).filter(Boolean))].map(n=>`<div class="note">动作备注：${esc(n)}</div>`).join('')}</div>`;}).join('');}
function setsReadOnly(sets){return `<div class="horizontal-scroll"><table class="set-table"><thead><tr><th>组</th><th>类型 / 状态</th><th>重量</th><th>次数</th><th>休息</th><th>RPE / RIR</th><th>备注 / 感受</th></tr></thead><tbody>${sets.map((s,i)=>`<tr><td>${s.exerciseInstanceNumber?s.exerciseInstanceNumber+'.':''}${s.setNumber||i+1}</td><td>${esc({work:'正式',warmup:'热身',drop:'递减',failure:'力竭'}[s.type]||s.type)} · <span class="${s.completed?'completion':''}">${s.completed?'完成':'未完成'}</span>${s.failed?' · 未达目标':''}</td><td>${s.weight??'—'} kg${s.weightText?' · '+esc(s.weightText):''}</td><td>${s.reps??'—'}</td><td>${s.restSeconds??'—'} 秒</td><td>${s.rpe??'—'} / ${s.rir??'—'}</td><td class="note">${esc(s.note||'—')}${s.durationSeconds?' · '+s.durationSeconds+' 秒':''}${s.speedKph?' · '+s.speedKph+' km/h':''}${s.inclinePercent?' · '+s.inclinePercent+'% 坡度':''}</td></tr>`).join('')}</tbody></table></div>`;}
function renderSettings(){const mode=S.storage?.mode||'server',d=S.data;$('#content').innerHTML=`<section class="card setting-block"><span class="eyebrow">DATA OWNERSHIP</span><h2>选择记录保存在哪里</h2><p>两种模式保留各自的数据。切换不会迁移、删除或双写记录，现有 MCP 授权会撤销。</p><div class="grid two-col"><div class="storage-option ${mode==='browser'?'selected':''}"><h3>用户本地浏览器</h3><p>训练、饮食、资料和目标仅保存在绑定设备的 IndexedDB。网站只中转 MCP 请求及结果，不保存记录副本。</p><p class="small">外部 AI 使用同一个网站 MCP 地址。此浏览器需保持在线；清除网站数据会删除本地记录，请定期导出备份。</p><button class="${mode==='browser'?'':'primary'}" data-action="storage-browser">${mode==='browser'&&S.storage?.deviceId===deviceId?'已绑定此浏览器':'选择并绑定此浏览器'}</button><span class="pill">${mode==='browser'&&S.storage?.deviceId===deviceId?'此页面在线':'需要绑定'}</span></div><div class="storage-option ${mode==='server'?'selected':''}"><h3>服务器 / App 会员云端</h3><p>记录保存在此实例服务器。连接 App 会员账户后，直接写入软件的同一账户云端格式，App 可同步读取。</p><p class="small">服务器模式可以在网页关闭时供 MCP 使用。个人数据按账号隔离，写入需要单独授权。</p><button class="${mode==='server'?'':'primary'}" data-action="storage-server">${mode==='server'?'当前模式':'选择服务器模式'}</button></div></div><div class="actions"><button data-action="export">导出当前记录 / App 兼容备份</button><label class="row">导入备份到当前模式<input type="file" id="import-file" accept="application/json,.json" style="max-width:210px"></label></div><p class="small muted">导出文件含个人记录，请自行保管。浏览器本地数据要进入 Flutter App，请在 App 的账号设置中导入此文件；这是手动导入，不是云端自动同步。</p></section><div class="grid two-col"><section class="card setting-block"><h2>连接 App 会员后端</h2><p class="muted">${d?.backend?.connected?'已连接：'+esc(d.backend.remoteUserId):'尚未连接 App 账户。连接后会切换为服务器模式。'}</p><p class="small muted">目标后端由部署者配置，网页不接受任意服务器地址。</p><form id="backend-form"><label>App 账号<input name="identifier" autocomplete="username" required></label><label>App 密码<input name="password" type="password" autocomplete="current-password" required></label><div class="actions"><button class="primary" type="submit">连接我的 App 账户</button><button type="button" data-action="sync-web-app">同步网页历史记录到 App</button><button type="button" data-action="disconnect-backend">断开连接</button></div></form><p class="small muted">连接 / 断开会撤销 MCP 令牌。网站保存加密会话，不保存密码。需要有效 App 会员。</p></section><section class="card setting-block"><h2>身体与训练资料</h2>${profileForm(d?.profile||{})}</section></div><section class="card setting-block"><span class="eyebrow">CONNECT YOUR AI</span><h2>让你的 AI 帮你记录</h2><p>复制网站 MCP 地址，默认选中全部读写权限，训练、饮食、身体资料、聊天和技能均可写入服务器；可取消勾选限制权限。令牌只显示一次，可随时撤销。</p><pre id="mcp-address">${esc(S.storage?.mcpUrl||location.origin+'/mcp')}</pre><button class="small" data-action="copy-mcp">复制 MCP 地址</button><form id="token-form" class="section-gap"><div class="form-grid"><label>连接名称<input name="label" placeholder="我的 AI" required></label><label>有效天数<input type="number" name="days" min="1" max="90" value="30" required></label></div><div class="checkbox-grid section-gap">${[['workouts','读取动作库 / 计划 / 训练'],['workouts.write','写入计划 / 当前训练 / 记录'],['nutrition','读取饮食 / 每日目标'],['nutrition.write','写入饮食 / 热量目标'],['profile','读取身体资料 / 体重'],['profile.write','写入身体资料 / 体重'],['skills','读取共享技能'],['skills.write','添加 / 修改 / 删除技能'],['chats','读取历史聊天记录'],['chats.write','保存 / 删除服务器聊天记录']].map(([k,v])=>`<label><input type="checkbox" name="scope" value="${k}" checked>${v}</label>`).join('')}</div><button class="primary section-gap" type="submit">创建 MCP 令牌</button></form><div id="new-token"></div><div id="tokens" class="section-gap"></div><details class="section-gap"><summary>连接与使用说明</summary><p class="small">在外部 AI 的远程 MCP 配置中填写此地址，使用 Authorization: Bearer &lt;令牌&gt;。传输为 Streamable HTTP。对外部署需可达的 HTTPS 域名；localhost 地址只能供当前电脑访问。仅接受 OAuth 的客户端需要额外 OAuth 支持，本项目目前使用 Bearer。</p><p class="small">例：先 search_app_exercises 查询动作 ID，再 save_training_plan 或 save_workout；每组保存 weight、reps、restSeconds、note。拍照给 AI 后，AI 调用 save_nutrition_entry 并标记 estimated；用 read_nutrition_day 查询真实目标、已摄入与剩余额度。每次独立写入使用唯一 idempotencyKey，重试重复使用同一键。</p><p class="small">用户本地模式：已绑定页面在线时，网站会将获授权请求中转到浏览器；离线返回 browser_device_offline。数据经过网站中转但不持久化在服务器。浏览器本地模式下聊天记录不提供，个人记录不写入服务器日志。</p></details></section><section class="card setting-block"><h2>给外部 AI 添加技能</h2><p class="muted">保存 Markdown 指令并选择是否允许外部 AI 获取；不会在服务器执行任意代码。</p><form id="skill-form" class="form-grid"><label>技能名称<input name="name" required></label><label>描述<input name="description"></label><label class="span-two">技能指令<textarea name="instructions" required placeholder="例如：先查询今日摄入和目标，再结合我的饮食偏好给建议。"></textarea></label><label class="row"><input name="external" type="checkbox" checked>共享给外部 AI</label><button class="primary" type="submit">添加技能</button></form><div class="section-gap">${(d?.skills||[]).filter(s=>!s.builtin).map(s=>`<div class="list-row"><div><strong>${esc(s.name)}</strong><p>${esc(s.description)} · ${s.external?'外部可用':'仅此账户'}</p></div><button class="quiet danger" data-delete-skill="${esc(s.id)}">删除</button></div>`).join('')}</div></section><div class="actions"><button class="quiet danger" data-action="logout">退出此账户</button></div>`;void loadTokens();}
function profileForm(p){return `<form id="profile-form" class="form-grid">${[['heightCm','身高 / cm'],['weightKg','体重 / kg'],['age','年龄'],['trainingYears','训练年限']].map(([k,l])=>`<label>${l}<input name="${k}" type="number" step="${['age'].includes(k)?'1':'0.1'}" value="${p[k]??''}"></label>`).join('')}<label>性别<select name="gender"><option value="">未填写</option>${['男','女','其他'].map(v=>`<option value="${({'男':'male','女':'female','其他':'other'})[v]}" ${p.gender===({'男':'male','女':'female','其他':'other'})[v]?'selected':''}>${v}</option>`).join('')}</select></label><label>目标<select name="goal"><option value="">未填写</option>${['增肌','减脂','维持','力量提升'].map(v=>`<option value="${({'增肌':'muscle_gain','减脂':'fat_loss','维持':'maintain','力量提升':'strength'})[v]}" ${p.goal===({'增肌':'muscle_gain','减脂':'fat_loss','维持':'maintain','力量提升':'strength'})[v]?'selected':''}>${v}</option>`).join('')}</select></label><label>活动水平<select name="activityLevel">${[['low','较低'],['moderate','中等'],['high','较高']].map(([k,v])=>`<option value="${k}" ${p.activityLevel===k?'selected':''}>${v}</option>`).join('')}</select></label><label>单次训练 / 分钟<input name="sessionMinutes" type="number" min="0" max="600" value="${p.sessionMinutes??60}"></label><label class="span-two">每周训练日（1–7，用逗号分隔）<input name="preferredWeekdays" value="${(p.preferredWeekdays||[]).join(',')}" placeholder="1,3,5"></label><label class="span-two">重点肌群（逗号分隔）<input name="focusMuscles" value="${(p.focusMuscles||[]).join(',')}" placeholder="胸,背,股四头"></label><button class="primary" type="submit">保存资料</button><p class="small muted">热量目标由外部 AI 根据这些资料与实际活动情况计算。</p></form>`;}
async function loadTokens(){if(!$('#tokens'))return;try{const {tokens}=await api('/tokens');if($('#tokens'))$('#tokens').innerHTML=tokens.map(t=>`<div class="list-row"><div><strong>${esc(t.label)}</strong><p>${esc(t.scopes.join(' · '))}<br>到期 ${fmtDate(t.expiresAt)} · ${t.revokedAt?'已撤销':'有效'}</p></div>${t.revokedAt?'':`<button class="danger small" data-revoke-token="${esc(t.id)}">撤销</button>`}</div>`).join('')||'<p class="muted">尚未创建连接。</p>';}catch(e){toast(errors[e.message]||e.message);}}
function download(name,data){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showDetail(id){const w=S.data.workouts.find(w=>w.id===id);if(!w)return;$('#detail-content').innerHTML=`<h2>${esc(w.name)}</h2><p>${fmtDate(w.date)} · ${w.effectiveSets} 组 · ${Math.round(w.volume)} kg · ${w.durationSeconds} 秒</p>${w.note?`<div class="note">整次训练：${esc(w.note)}</div>`:''}${w.exercises.map(e=>`<div class="exercise-card"><h3>${esc(nameOf(e))}</h3>${setsReadOnly(e.sets)}${e.note?`<div class="note">动作备注：${esc(e.note)}</div>`:''}</div>`).join('')}<button class="danger" data-delete-record="workout:${esc(w.id)}">删除记录</button>`;$('#detail-dialog').showModal();}
// Delegated controls keep all user input text escaped and leave recorded values intact.
document.addEventListener('click',safeTask(async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.page){S.page=button.dataset.page;render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}
 if(button.dataset.muscle){showMuscle(button.dataset.muscle);return;}if(button.dataset.detail){showDetail(button.dataset.detail);return;}
 if(button.dataset.editWorkout){newDraft(false,S.data.workouts.find(w=>w.id===button.dataset.editWorkout));return;}if(button.dataset.editPlan){newDraft(true,S.data.plans.find(w=>w.id===button.dataset.editPlan));return;}
 if(button.dataset.startPlan){const plan=S.data.plans.find(p=>p.id===button.dataset.startPlan);S.draft=null;newDraft(false);S.draft.name=plan.name;S.draft.exercises=plan.exercises.map(e=>({...cleanExercise(e),id:uid(),sets:e.sets.map(s=>({...s,id:uid(),plannedWeight:s.plannedWeight??s.weight,weight:s.plannedWeight??s.weight,completed:false}))}));persistDraft();render();return;}
 if(button.dataset.equipment){await openEquipment(button.dataset.equipment);return;}
 if(button.dataset.deleteEquipment){await api('/exercise-equipment',{exerciseId:S.equipmentExercise,equipmentId:button.dataset.deleteEquipment,action:'delete'});await openEquipment(S.equipmentExercise);return;}
 if(button.dataset.addExercise){if(!S.draft||S.editor!=='workout'&&pickingForLibrary)newDraft(false);const info=S.catalog.get(button.dataset.addExercise);S.draft.exercises.push({id:uid(),exerciseId:info.id,name:info.name,restSeconds:90,note:'',sets:[setDefaults(),setDefaults(),setDefaults()]});persistDraft();$('#exercise-dialog').close();render();return;}
 if(button.dataset.addSet!==undefined){S.draft.exercises[num(button.dataset.addSet)].sets.push(setDefaults());persistDraft();render();return;}
 if(button.dataset.moveExercise){const [i,delta]=button.dataset.moveExercise.split(':').map(Number),j=i+delta;if(j>=0&&j<S.draft.exercises.length){[S.draft.exercises[i],S.draft.exercises[j]]=[S.draft.exercises[j],S.draft.exercises[i]];persistDraft();render();}return;}
 if(button.dataset.removeExercise!==undefined){S.draft.exercises.splice(num(button.dataset.removeExercise),1);persistDraft();render();return;}if(button.dataset.removeSet){const [i,j]=button.dataset.removeSet.split(':').map(Number);S.draft.exercises[i].sets.splice(j,1);persistDraft();render();return;}
 if(button.dataset.exerciseHistory){S.progressId=button.dataset.exerciseHistory;S.page='progress';render();return;}
 if(button.dataset.editMeal){const meal=S.data.nutrition.find(m=>m.id===button.dataset.editMeal),f=$('#nutrition-form');for(const k of ['foodName','mealType','amount','calories','proteinGrams','carbsGrams','fatGrams','note'])f.elements[k].value=meal[k]??'';f.elements.recordedAt.value=localInput(meal.recordedAt);f.elements.estimated.checked=!!meal.estimated;f.dataset.recordId=meal.id;f.dataset.version=meal.updatedAt||'';f.querySelector('[type=submit]').textContent='保存调整';f.scrollIntoView({behavior:'smooth'});return;}
 if(button.dataset.deleteRecord){if(!confirm('删除这条记录？此操作只影响当前选择的存储。'))return;const [kind,id]=button.dataset.deleteRecord.split(':');await api('/records/'+kind,{action:'delete',recordId:id,idempotencyKey:uid()});$('#detail-dialog').close();toast('记录已删除。');await refresh();return;}
 if(button.dataset.revokeToken){await api('/tokens/'+encodeURIComponent(button.dataset.revokeToken),undefined,'DELETE');await loadTokens();toast('授权已撤销。');return;}
 if(button.dataset.deleteSkill){await api('/skills/'+encodeURIComponent(button.dataset.deleteSkill),undefined,'DELETE');await refresh();return;}
 if(button.dataset.action==='sync-web-app'){const r=await api('/backend/import',{});toast('已同步 '+r.saved+' 条记录、'+r.media+' 个素材；失败 '+r.errors.length+' 项。');await refresh();return;}
 switch(button.dataset.action){case 'login':$('#login-dialog').showModal();break;case 'logout':logout();break;case 'new-workout':if(!S.token){$('#login-dialog').showModal();break;}newDraft(false);break;case 'new-plan':newDraft(true);break;case 'pick-exercise':await openExercises();break;case 'pick-exercise-library':await openExercises(true);break;case 'close-exercises':$('#exercise-dialog').close();break;case 'close-detail':$('#detail-dialog').close();break;case 'toggle-body-mode':S.anatomyMode=S.anatomyMode==='recovery'?'volume':'recovery';render();break;case 'toggle-gender':S.bodyGender=S.bodyGender==='male'?'female':'male';render();break;case 'save-draft':await saveDraft();break;case 'save-active':await saveDraft(true);break;case 'reload-active':if(confirm('载入已保存的当前训练？此浏览器未保存的草稿修改将替换。')){const current=(await api('/bootstrap')).activeWorkout;if(!current)throw new Error('没有已保存的当前训练。');S.draft=current;S.editId=null;S.editor='workout';S.key=uid();persistDraft();render();}break;case 'discard-draft':if(confirm('清空此浏览器的编辑草稿？已保存记录不会删除。')){S.draft=null;S.restEnd=0;persistDraft();render();}break;case 'rest-add':S.restEnd+=15000;persistDraft();break;case 'rest-skip':S.restEnd=0;persistDraft();tickTimers();break;case 'add-water':await save('nutrition',{recordedAt:new Date(S.day+'T12:00:00+08:00').toISOString(),mealType:'饮水',foodName:'饮水',calories:0,waterMl:250});await refresh();toast('已记录饮水 250 ml。');break;case 'storage-browser':case 'storage-server':{const mode=button.dataset.action==='storage-browser'?'browser':'server';if(!confirm(`切换为${mode==='browser'?'此浏览器本地':'服务器'}存储？原记录保留，不自动迁移；已有 MCP 授权会撤销。`))break;S.bridgeStop?.();await api('/storage',{mode,deviceId});S.data=null;S.draft=null;await load();S.page='settings';render();break;}case 'disconnect-backend':await api('/backend',undefined,'DELETE');await load();break;case 'copy-mcp':await navigator.clipboard.writeText($('#mcp-address').textContent);toast('MCP 地址已复制。');break;case 'export':{const d=S.storage?.mode==='browser'?await executeDeviceOperation(S.storage.userId,{type:'read'}):await api('/export');download('traintool-backup-'+today()+'.json',{schemaVersion:2,source:'traintool-web',exportedAt:new Date().toISOString(),workoutHistory:d.workouts,trainingLibrary:{routines:d.plans,routineFolders:[...new Set(d.plans.map(p=>p.folder))]},trainingProfile:{profile:d.profile},nutrition:d.nutrition,weight:d.weight,nutritionGoals:d.nutritionGoals,activeWorkout:d.activeWorkout});toast('备份已导出，可在 App 中导入。');break;}}
}));
document.addEventListener('input',e=>{const el=e.target;const form=el.closest('form');if(form)delete form.dataset.requestKey;if(el.dataset.draft){S.draft[el.dataset.draft]=el.dataset.draft==='date'?isoLocal(el.value):el.dataset.draft==='durationSeconds'?num(el.value):el.value;persistDraft();}if(el.dataset.set){const s=S.draft.exercises[num(el.dataset.i)].sets[num(el.dataset.j)],key=el.dataset.set;s[key]=el.type==='checkbox'?el.checked:['note','type','weightText'].includes(key)?el.value:el.value===''?null:num(el.value);if(key==='completed'&&el.checked&&S.editor==='workout'){S.restEnd=Date.now()+s.restSeconds*1000;tickTimers();}persistDraft();}if(el.dataset.exercise){S.draft.exercises[num(el.dataset.i)][el.dataset.exercise]=el.dataset.exercise==='restSeconds'?num(el.value):el.value;persistDraft();}});
$('#exercise-query').addEventListener('input',()=>{clearTimeout(searchExercises.timer);searchExercises.timer=setTimeout(safeTask(searchExercises),180);});for(const id of ['#muscle-filter','#equipment-filter'])$(id).addEventListener('change',safeTask(searchExercises));
document.addEventListener('change',safeTask(async e=>{if(e.target.id==='nutrition-date'){S.day=e.target.value;await renderNutrition();}if(e.target.id==='progress-exercise'){S.progressId=e.target.value;await loadProgress();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw new Error('备份超过 8 MiB。');const data=JSON.parse(await file.text());if(!confirm('将文件中的记录合并到当前存储？原记录保留，同 ID 的现有记录不会覆盖。'))return;await importBackup(data);await refresh();toast('备份已导入。');}}));
async function importBackup(data){let count=0;for(const [kind,list] of [['workout',data.workoutHistory||[]],['plan',data.trainingLibrary?.routines||[]],['nutrition',data.nutrition||[]],['weight',data.weight||[]],['nutritionGoals',data.nutritionGoals||[]]]){const existing=new Set((kind==='workout'?S.data.workouts:kind==='plan'?S.data.plans:S.data[kind]||[]).map(r=>r.id));for(const entry of list){if(existing.has(entry.id))continue;let record;if(kind==='workout'||kind==='plan'){record={name:entry.name,note:entry.note||'',exercises:entry.exercises.map(cleanExercise)};if(kind==='plan')record.folder=entry.folder||'导入';else Object.assign(record,{date:entry.date,durationSeconds:entry.durationSeconds||0,startTime:entry.startTime});}else {const allowed=kind==='nutrition'?['recordedAt','mealType','foodName','amount','calories','proteinGrams','carbsGrams','fatGrams','waterMl','recognitionWarnings','recognitionReviewed','estimated','note']:kind==='weight'?['recordedAt','weightKg','bodyFatPercent','note']:['date','calories','goalType','basis','source'];record=Object.fromEntries(Object.entries(entry).filter(([k])=>allowed.includes(k)));}await save(kind,record,undefined,undefined,'import:'+kind+':'+entry.id);count++;}}if(data.trainingProfile?.profile)await save('profile',Object.fromEntries(Object.entries(data.trainingProfile.profile).filter(([k])=>!['id','updatedAt'].includes(k))),undefined,undefined,'import-profile:'+uid());return count;}
document.addEventListener('submit',safeTask(async e=>{const f=e.target;if(f.id==='login-form')return;e.preventDefault();const form=new FormData(f),values=Object.fromEntries(form);const submit=f.querySelector('[type=submit]');f.dataset.requestKey ||= uid();submit.disabled=true;try{if(f.id==='equipment-form'){const file=$('#equipment-photo').files[0];const body={exerciseId:S.equipmentExercise,name:values.name};if(file){const r=await fetch('/v1/agent/exercise-media?exerciseId='+encodeURIComponent(S.equipmentExercise)+'&name='+encodeURIComponent(values.name),{method:'PUT',headers:{authorization:'Bearer '+S.token,'content-type':file.type},body:file});const uploaded=await r.json();if(!r.ok)throw Error(uploaded.error||'上传失败');if(f.dataset.equipmentId)await api('/exercise-equipment',{exerciseId:S.equipmentExercise,equipmentId:f.dataset.equipmentId,action:'delete'});toast('动作照片 / 视频已保存到服务器，与 App 共用。');await openEquipment(S.equipmentExercise);return;}if(f.dataset.equipmentId)body.equipmentId=f.dataset.equipmentId;await api('/exercise-equipment',body);toast('器械名称和照片已保存到服务器。');await openEquipment(S.equipmentExercise);}if(f.id==='nutrition-form'){const record={...values,recordedAt:isoLocal(values.recordedAt),calories:num(values.calories),proteinGrams:num(values.proteinGrams),carbsGrams:num(values.carbsGrams),fatGrams:num(values.fatGrams),estimated:form.has('estimated'),recognitionReviewed:true};await save('nutrition',record,f.dataset.recordId,f.dataset.version,f.dataset.requestKey);toast('饮食记录已保存。');await refresh();}if(f.id==='goal-form'){await save('nutritionGoals',{date:S.day,calories:num(values.calories),goalType:values.goalType,basis:values.basis,source:values.source},f.dataset.recordId,f.dataset.version,f.dataset.requestKey);toast('每日目标已保存。');await refresh();}if(f.id==='weight-form'){await save('weight',{recordedAt:isoLocal(values.recordedAt),weightKg:num(values.weightKg),...(values.bodyFatPercent?{bodyFatPercent:num(values.bodyFatPercent)}:{}),note:values.note},undefined,undefined,f.dataset.requestKey);await refresh();toast('体重记录已保存。');}if(f.id==='profile-form'){const profile={...values,preferredWeekdays:values.preferredWeekdays.split(/[,，]/).map(Number).filter(n=>n>=1&&n<=7),focusMuscles:values.focusMuscles.split(/[,，]/).map(v=>v.trim()).filter(Boolean)};for(const k of ['heightCm','weightKg','age','trainingYears','sessionMinutes'])if(values[k]!=='')profile[k]=num(values[k]);else delete profile[k];if(!profile.gender)delete profile.gender;if(!profile.goal)delete profile.goal;await save('profile',profile,undefined,undefined,f.dataset.requestKey);await refresh();toast('个人资料已保存。');}if(f.id==='backend-form'){await api('/backend',values);await api('/storage',{mode:'server'});S.draft=null;await load();toast('已连接 App 会员账户。');}if(f.id==='token-form'){const grant=await api('/tokens',{label:values.label,days:num(values.days),scopes:form.getAll('scope')});$('#new-token').innerHTML='<h3 class="section-gap">令牌仅显示一次</h3><pre></pre><p class="small muted">请保存到外部 AI 的授权设置，不要分享。模式切换或撤销后失效。</p>';$('#new-token pre').textContent=JSON.stringify({url:grant.url,transport:'streamable-http',headers:{Authorization:'Bearer '+grant.token}},null,2);await loadTokens();}if(f.id==='skill-form'){await api('/skills',{...values,external:form.has('external'),enabled:true});await refresh();toast('技能已添加。');}}finally{submit.disabled=false;}}));
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target;try{const values=Object.fromEntries(new FormData(f));const login=values.accountType==='app'?await auth('phone/login',values):await api(f.dataset.register==='true'?'/register':'/login',values);S.token=login.session.token;sessionStorage.setItem('kilo-web-token',S.token);f.elements.password.value='';$('#login-dialog').close();await load();}catch(err){$('#login-error').textContent=errors[err.message]||err.message;}});
$('#login-close').onclick=()=>$('#login-dialog').close();$('#account').onclick=()=>S.token?logout():$('#login-dialog').showModal();
function logout(){S.bridgeStop?.();S.token=null;S.data=null;S.draft=null;S.storage=null;sessionStorage.removeItem('kilo-web-token');render();}
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('kilo-web-theme',document.body.classList.contains('dark')?'dark':'light');};if((localStorage.getItem('kilo-web-theme')||'dark')==='dark')document.body.classList.add('dark');
function tickTimers(){const format=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`,timer=$('#workout-timer');if(timer)timer.textContent=format(Math.max(0,Math.floor((Date.now()-(S.startedAt||Date.now()))/1000)));const rest=$('#rest-time'),banner=$('#rest-banner');if(rest&&banner){const left=Math.max(0,Math.ceil((S.restEnd-Date.now())/1000));rest.textContent=format(left);banner.hidden=!left;}}
setInterval(tickTimers,1000);setInterval(()=>{if(S.token&&S.data&&!S.draft&&['home','progress'].includes(S.page)&&document.visibilityState==='visible')void refresh().catch(()=>{});},25000);
render();if(S.token)load().catch(err=>toast(errors[err.message]||err.message));

async function equipmentPhoto(file){if(!file.type.startsWith('image/'))throw Error('请选择图片');if(file.size>20*1024*1024)throw Error('原图不能超过20MB');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let photo=canvas.toDataURL('image/jpeg',0.8);if(photo.length>1400000)photo=canvas.toDataURL('image/jpeg',0.5);if(photo.length>1400000)throw Error('图片过大，请选择更小的图片');return photo;}
async function openEquipment(exerciseId){S.equipmentExercise=exerciseId;let dialog=$('#equipment-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='equipment-dialog';document.body.append(dialog);}const d=await api('/exercise-equipment?exerciseId='+encodeURIComponent(exerciseId));dialog.innerHTML=`<div class="dialog-head"><h2>${esc(S.catalog.get(exerciseId)?.name||exerciseId)} · 我的器械</h2><button type="button" id="equipment-close">关闭</button></div><p>拍摄健身房器械并填写名称，照片与此动作关联，保存到你的服务器账户。</p><form id="equipment-form"><label>器械名称<input name="name" maxlength="100" required placeholder="例如：健身房一号胸推机"></label><label>选择动作照片 / 视频<input id="equipment-photo" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" required></label><button type="button" id="equipment-camera">使用相机拍照</button><button type="submit" class="primary">保存器械</button></form><div>${d.records.map(r=>`<section class="card section-gap"><h3>${esc(r.name)}</h3>${r.photo?`<img src="${esc(r.photo)}" alt="${esc(r.name)}" style="max-width:100%;max-height:300px">`:`<div data-asset-preview="${esc(r.id)}"></div>`}<div class="actions"><button type="button" data-edit-equipment="${esc(r.id)}">修改名称 / 照片</button><button type="button" data-delete-equipment="${esc(r.id)}">删除</button></div></section>`).join('')}</div>`;$('#equipment-close').onclick=()=>dialog.close();$('#equipment-camera').onclick=()=>{const input=$('#equipment-photo');input.setAttribute('capture','environment');input.click();input.removeAttribute('capture');};dialog.querySelectorAll('[data-edit-equipment]').forEach(button=>button.onclick=()=>{const r=d.records.find(r=>r.id===button.dataset.editEquipment);const f=$('#equipment-form');f.dataset.equipmentId=r.id;f.elements.name.value=r.name;$('#equipment-photo').required=false;f.querySelector('[type=submit]').textContent='保存修改';});if(!dialog.open)dialog.showModal();for(const r of d.records.filter(r=>r.mediaUrl)){const response=await fetch('/v1/agent/exercise-media/'+r.id,{headers:{authorization:'Bearer '+S.token}});if(!response.ok)continue;const objectUrl=URL.createObjectURL(await response.blob());const el=document.createElement(r.contentType.startsWith('video/')?'video':'img');el.src=objectUrl;el.style.cssText='max-width:100%;max-height:300px';if(el.tagName==='VIDEO'){el.controls=true;el.playsInline=true;}dialog.querySelector('[data-asset-preview="'+r.id+'"]')?.append(el);dialog.addEventListener('close',()=>URL.revokeObjectURL(objectUrl),{once:true});}}

$('#web-register-toggle').onclick=()=>{const f=$('#login-form');f.dataset.register=f.dataset.register==='true'?'false':'true';f.elements.accountType.value='web';f.querySelector('[type=submit]').textContent=f.dataset.register==='true'?'注册网页账号':'登录';$('#login-error').textContent='用户名：3–40 位英文、数字、下划线或短横线；密码至少 8 位。';};
if(new URLSearchParams(location.search).has('register')){$('#web-register-toggle').click();if(!$('#login-dialog').open)$('#login-dialog').showModal();}
